package zone.moddev.mc.ironagearchitecture;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.*;
import zone.moddev.mc.ironagearchitecture.block.*;

public class SmartThatchGeometryTest {
    static double height(ThatchShape s,double x,double z){EnumFacing inverse=s.facing==EnumFacing.EAST?EnumFacing.WEST:s.facing==EnumFacing.WEST?EnumFacing.EAST:s.facing;double[] q=RoofGeometry.rotate(x,0,z,inverse);return s.height(q[0],q[2]);}
    static ThatchShape shape(Map<String,Integer> roof,int x,int z){int[] h=new int[9];int y=roof.get(x+","+z);for(int dz=-1;dz<=1;dz++)for(int dx=-1;dx<=1;dx++)h[(dz+1)*3+dx+1]=roof.containsKey((x+dx)+","+(z+dz))?roof.get((x+dx)+","+(z+dz))-y:9;return ThatchShape.select(h);}
    static void joins(Map<String,Integer> roof){for(String p:roof.keySet()){String[] q=p.split(",");int x=Integer.parseInt(q[0]),z=Integer.parseInt(q[1]),y=roof.get(p);ThatchShape a=shape(roof,x,z);for(int[] d:new int[][]{{1,0},{0,1}}){Integer other=roof.get((x+d[0])+","+(z+d[1]));if(other==null)continue;ThatchShape b=shape(roof,x+d[0],z+d[1]);for(int i=0;i<=16;i++){double t=i/16.0,ah=y+height(a,d[0]==1?1:t,d[0]==1?t:1),bh=other+height(b,d[0]==1?0:t,d[0]==1?t:0);assertEquals("Roof seam "+p+" to "+(x+d[0])+","+(z+d[1])+" at "+t,ah,bh,1e-9);}}}}
    @Test public void straightSlopesArePlanesInEveryFacing(){for(EnumFacing d:EnumFacing.HORIZONTALS){ThatchShape s=ThatchShape.of(ThatchForm.SLOPE,d);for(int i=0;i<=16;i++){double t=i/16.0;double[] p=RoofGeometry.rotate(.37,0,t,d);assertEquals(1-t,height(s,p[0],p[2]),1e-9);}}}
    @Test public void gableAndHipCoursesShareExactEdges(){for(boolean hip:new boolean[]{false,true}){Map<String,Integer> r=new HashMap<>();for(int x=0;x<9;x++)for(int z=0;z<9;z++)r.put(x+","+z,hip?Math.min(Math.min(x,8-x),Math.min(z,8-z)):Math.min(x,8-x));joins(r);}}
    @Test public void steppedOvalHasNoMismatchingEdges(){Map<String,Integer> r=new HashMap<>();for(int x=-7;x<=7;x++)for(int z=-6;z<=6;z++)if(Math.abs(x)+Math.abs(z)<=10){int distance=20;for(int dx=-15;dx<=15;dx++)for(int dz=-15;dz<=15;dz++)if(Math.abs(x+dx)+Math.abs(z+dz)>10)distance=Math.min(distance,Math.max(Math.abs(dx),Math.abs(dz)));r.put(x+","+z,Math.max(0,distance-2));}joins(r);}
    @Test public void isolatedAndPointOnlyContactsStayFlat(){int[] h={1,9,9,9,0,9,9,9,9};assertEquals(ThatchShape.FLAT_PROFILE,ThatchShape.select(h).profile);}
    @Test public void finiteStencilChoicesAreInterned(){for(int code=0;code<65536;code++){int[] h=new int[9];Arrays.fill(h,9);h[4]=0;int n=code;for(int i=0;i<9;i++)if(i!=4){int v=n&3;h[i]=v==3?9:v-1;n>>=2;}ThatchShape s=ThatchShape.select(h);assertSame(s,ThatchShape.select(h));assertTrue(s.code<ThatchShape.COUNT*4);}}
    @Test public void everyStateReusesAContainedMesh(){assertEquals(56,ThatchShape.COUNT);for(int p=0;p<ThatchShape.COUNT;p++)for(EnumFacing d:EnumFacing.HORIZONTALS){ThatchShape s=ThatchShape.of(p,d);ThatchGeometry.Mesh m=ThatchGeometry.mesh(s);assertSame(m,ThatchGeometry.mesh(s));assertTrue(m.faces.size()<=48);assertFalse(m.faces.isEmpty());assertTrue(m.boxes.size()<=1024);for(ThatchGeometry.Face f:m.faces)for(double[] v:f.vertices)for(double n:v)assertTrue(n>=0&&n<=1);}}
    @Test public void exactRayUsesThePlane(){ThatchGeometry.Mesh m=ThatchGeometry.mesh(ThatchShape.of(ThatchForm.SLOPE,EnumFacing.NORTH));BlockPos p=new BlockPos(12,80,32);RayTraceResult r=m.trace(p,new Vec3d(12.37,83,32.41),new Vec3d(12.37,79,32.41));assertNotNull(r);assertEquals(80.59,r.hitVec.yCoord,1e-9);assertEquals(EnumFacing.UP,r.sideHit);}
    @Test public void allFacesHaveValidWinding(){for(int p=0;p<ThatchShape.COUNT;p++)for(EnumFacing d:EnumFacing.HORIZONTALS)for(ThatchGeometry.Face f:ThatchGeometry.mesh(ThatchShape.of(p,d)).faces){double len=0;for(double n:f.normal)len+=n*n;assertEquals(1,len,1e-9);if(f.surface)assertTrue(f.normal[1]>0);for(int i=1;i+1<f.vertices.length;i++){double[] a=f.vertices[0],b=f.vertices[i],c=f.vertices[i+1];double x=(b[1]-a[1])*(c[2]-a[2])-(b[2]-a[2])*(c[1]-a[1]),y=(b[2]-a[2])*(c[0]-a[0])-(b[0]-a[0])*(c[2]-a[2]),z=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);assertTrue(x*f.normal[0]+y*f.normal[1]+z*f.normal[2]>0);}}}
    @Test public void collisionStaysWithinOneSixteenth(){for(int p=0;p<ThatchShape.COUNT;p++){ThatchShape s=ThatchShape.of(p,EnumFacing.NORTH);ThatchGeometry.Mesh mesh=ThatchGeometry.mesh(s);for(int x=0;x<32;x++)for(int z=0;z<32;z++){double px=(x+.37)/32,pz=(z+.37)/32,h=s.height(px,pz),top=0;for(AxisAlignedBB b:mesh.boxes)if(px>=b.minX&&px<=b.maxX&&pz>=b.minZ&&pz<=b.maxZ)top=Math.max(top,b.maxY);assertTrue(top+1e-9>=h);assertTrue("profile="+p+" error="+(top-h),top-h<=1/16.0+1e-9);}}}

    @Test public void slopingSkinKeepsItsThicknessAcrossTheCellFloor(){ThatchShape s=ThatchShape.of(ThatchForm.SLOPE,EnumFacing.NORTH);BlockPos p=new BlockPos(0,80,0);for(double z:new double[]{.2,.6,.8}){double top=80+1-z,bottom=top-ThatchGeometry.THICKNESS;Vec3d a=new Vec3d(.37,78,z),b=new Vec3d(.37,82,z);RayTraceResult lower=ThatchGeometry.underside(s).trace(p.down(),a,b),upper=ThatchGeometry.mesh(s).trace(p,a,b);RayTraceResult hit=lower==null?upper:upper==null?lower:lower.hitVec.yCoord<upper.hitVec.yCoord?lower:upper;assertNotNull(hit);assertEquals(bottom,hit.hitVec.yCoord,1e-9);assertEquals(.5,top-hit.hitVec.yCoord,1e-9);}}
    @Test public void skinLeavesUsableSpaceBelowItsHighSide(){ThatchGeometry.Mesh m=ThatchGeometry.mesh(ThatchShape.of(ThatchForm.SLOPE,EnumFacing.NORTH));AxisAlignedBB head=new AxisAlignedBB(.4,.05,.05,.6,.2,.15);for(AxisAlignedBB box:m.boxes)assertFalse(box.intersectsWith(head));}
    @Test public void simpleRoofsUseSmallMergedMeshes(){for(ThatchForm f:new ThatchForm[]{ThatchForm.FLAT,ThatchForm.SLOPE,ThatchForm.RIDGE}){ThatchShape s=ThatchShape.of(f,EnumFacing.NORTH);int faces=ThatchGeometry.mesh(s).faces.size()+ThatchGeometry.underside(s).faces.size();System.out.println("THATCH_MERGED "+f+" faces="+faces);assertTrue(faces<=20);}assertSame(ThatchGeometry.EMPTY,ThatchGeometry.underside(ThatchShape.of(ThatchForm.FLAT,EnumFacing.NORTH)));}
    @Test public void bothFragmentsHaveClosedOutwardFaces(){for(int p=0;p<ThatchShape.COUNT;p++)for(EnumFacing d:EnumFacing.HORIZONTALS){ThatchShape s=ThatchShape.of(p,d);for(int part=0;part<2;part++){ThatchGeometry.Mesh m=part==0?ThatchGeometry.mesh(s):ThatchGeometry.underside(s);assertTrue(m.faces.size()<=48);for(ThatchGeometry.Face f:m.faces){double[] centre=new double[3];double sum=0;for(int i=0;i<f.vertices.length;i++)sum+=(i+1)*(i+2);for(int i=0;i<f.vertices.length;i++)for(int a=0;a<3;a++){double[] v=f.vertices[i];centre[a]+=v[a]*(i+1)*(i+2)/sum;assertTrue(v[a]>=-1e-9&&v[a]<=1+1e-9);}double[] inside=new double[3],outside=new double[3];for(int a=0;a<3;a++){inside[a]=centre[a]-f.normal[a]*1e-5;outside[a]=centre[a]+f.normal[a]*1e-5;}assertTrue("inward face profile="+p+" part="+part+" facing="+d+" vertices="+Arrays.deepToString(f.vertices)+" normal="+Arrays.toString(f.normal)+" point="+Arrays.toString(inside)+" h="+height(s,inside[0],inside[2]),volume(s,part,inside));assertFalse("open face profile="+p+" part="+part,volume(s,part,outside));}}}}
    static boolean volume(ThatchShape s,int part,double[] v){for(double n:v)if(n<0||n>1)return false;if(s.profile==ThatchShape.SOLID_PROFILE)return part==0;double top=height(s,v[0],v[2]),y=v[1]-part;return y>=top-ThatchGeometry.THICKNESS-1e-9&&y<=top+1e-9;}
}
